"use strict";

const http = require("http");
const crypto = require("crypto");

// Feature flag SDK for cloud infrastructure
class FeatureFlagClient {
  constructor(options = {}) {
    this.apiHost = options.apiHost || "flags.internal.service";
    this.apiPort = options.apiPort || 8080;
    this.sdkKey = options.sdkKey || "";
    this.flagCache = new Map();
    this.userAgent = `CloudSDK/2.4.1 (${process.platform})`;
    this.connectionPool = [];
    this.maxPoolSize = options.maxPoolSize || 5;
    this.requestTimeout = options.requestTimeout || 5000;
    this.enableStreaming = options.enableStreaming !== false;
    this.chunkEncoding = options.chunkEncoding || "identity";
  }

  // Validate a header name/value to prevent CRLF (header) injection
  _validateHeader(name, value) {
    const nameStr = String(name);
    const valueStr = String(value);
    // Header field names: token chars only per RFC 7230 (no controls, no separators like CR/LF)
    if (!/^[!#$%&'*+\-.^_`|~0-9A-Za-z]+$/.test(nameStr)) {
      throw new Error(`Invalid header name: ${nameStr}`);
    }
    // Reject any control characters (CR, LF, NUL, etc.) in the value
    if (/[\r\n\0]/.test(valueStr) || /[\x00-\x08\x0A-\x1F\x7F]/.test(valueStr)) {
      throw new Error(`Invalid header value for ${nameStr}`);
    }
  }

  // Build headers for flag evaluation request
  _buildHeaders(context) {
    const headers = {
      "Host": this.apiHost,
      "User-Agent": this.userAgent,
      "X-SDK-Key": this.sdkKey,
      "X-Request-ID": crypto.randomUUID(),
      "Accept": "application/json",
      "Connection": "keep-alive"
    };
    if (context && context.customHeaders) {
      for (const [key, value] of Object.entries(context.customHeaders)) {
        // Sanitize/validate user-supplied headers before merging
        this._validateHeader(key, value);
        headers[key] = value;
      }
    }
    return headers;
  }

  // Serialize evaluation context for the request body
  _serializeContext(evalContext) {
    const payload = JSON.stringify({
      key: evalContext.userKey,
      attributes: evalContext.attributes || {},
      environment: evalContext.environment || "production"
    });
    return payload;
  }

  // Construct raw HTTP request with proper framing
  _buildRawRequest(method, path, headers, body) {
    let requestLine = `${method} ${path} HTTP/1.1\r\n`;
    let headerBlock = "";

    // Add Content-Length based on body
    if (body !== null && body !== undefined) {
      headers["Content-Type"] = "application/json";
      // Use Transfer-Encoding if chunk encoding is enabled
      if (this.chunkEncoding === "chunked" && body.length > 128) {
        headers["Transfer-Encoding"] = "chunked";
        // Do NOT include Content-Length when using chunked encoding
        // per RFC 7230 Section 3.3.2 - they are mutually exclusive
      } else {
        headers["Content-Length"] = Buffer.byteLength(body).toString();
      }
    }

    for (const [key, value] of Object.entries(headers)) {
      // Defense-in-depth: validate every header written to the raw request
      this._validateHeader(key, value);
      headerBlock += `${key}: ${value}\r\n`;
    }

    let rawRequest = requestLine + headerBlock + "\r\n";

    if (body !== null && body !== undefined) {
      if (headers["Transfer-Encoding"] === "chunked") {
        rawRequest += this._chunkEncode(body);
      } else {
        rawRequest += body;
      }
    }

    return rawRequest;
  }

  // Chunk-encode a body per HTTP/1.1 spec
  _chunkEncode(body) {
    const chunkSize = 64;
    let encoded = "";
    for (let i = 0; i < body.length; i += chunkSize) {
      const chunk = body.slice(i, i + chunkSize);
      encoded += chunk.length.toString(16) + "\r\n";
      encoded += chunk + "\r\n";
    }
    encoded += "0\r\n\r\n";
    return encoded;
  }

  // Send raw request over TCP socket (for performance)
  _sendRawRequest(rawRequest) {
    return new Promise((resolve, reject) => {
      const net = require("net");
      const socket = new net.Socket();
      let responseData = "";

      socket.setTimeout(this.requestTimeout);
      socket.connect(this.apiPort, this.apiHost, () => {
        socket.write(rawRequest);
      });

      socket.on("data", (data) => {
        responseData += data.toString();
      });

      socket.on("end", () => {
        resolve(this._parseResponse(responseData));
      });

      socket.on("timeout", () => {
        socket.destroy();
        reject(new Error("Request timeout"));
      });

      socket.on("error", reject);
    });
  }

  // Parse HTTP response
  _parseResponse(raw) {
    const headerEnd = raw.indexOf("\r\n\r\n");
    if (headerEnd === -1) return { status: 0, body: null };
    const headerSection = raw.slice(0, headerEnd);
    const body = raw.slice(headerEnd + 4);
    const statusLine = headerSection.split("\r\n")[0];
    const statusCode = parseInt(statusLine.split(" ")[1], 10);
    try {
      return { status: statusCode, body: JSON.parse(body) };
    } catch {
      return { status: statusCode, body: body };
    }
  }

  // Evaluate a feature flag for a given context
  async evaluate(flagKey, evalContext, defaultValue = false) {
    const cacheKey = `${flagKey}:${evalContext.userKey}`;
    if (this.flagCache.has(cacheKey)) {
      const cached = this.flagCache.get(cacheKey);
      if (Date.now() - cached.ts < 30000) return cached.value;
    }

    const path = `/api/v2/flags/${encodeURIComponent(flagKey)}/evaluate`;
    const headers = this._buildHeaders(evalContext);
    const body = this._serializeContext(evalContext);
    const rawRequest = this._buildRawRequest("POST", path, headers, body);

    try {
      const response = await this._sendRawRequest(rawRequest);
      if (response.status === 200 && response.body) {
        const value = response.body.value !== undefined ? response.body.value : defaultValue;
        this.flagCache.set(cacheKey, { value, ts: Date.now() });
        return value;
      }
    } catch (err) {
      console.error(`Flag evaluation failed for ${flagKey}:`, err.message);
    }
    return defaultValue;
  }

  // Batch evaluate multiple flags
  async batchEvaluate(flagKeys, evalContext) {
    const results = {};
    const path = "/api/v2/flags/batch-evaluate";
    const headers = this._buildHeaders(evalContext);
    const body = JSON.stringify({
      flags: flagKeys,
      context: {
        key: evalContext.userKey,
        attributes: evalContext.attributes || {}
      }
    });
    const rawRequest = this._buildRawRequest("POST", path, headers, body);

    try {
      const response = await this._sendRawRequest(rawRequest);
      if (response.status === 200 && response.body && response.body.evaluations) {
        for (const eval_ of response.body.evaluations) {
          results[eval_.flag] = eval_.value;
        }
      }
    } catch (err) {
      console.error("Batch evaluation failed:", err.message);
    }
    return results;
  }
}

module.exports = { FeatureFlagClient };
